 // Private preparation is temporary, outside ops/widgetState and localStorage.
 const LD=globalThis.RodavoltLegalDocuments;
 let legalDraft={ids:['rental'],values:{}};
 function legalDocumentsPanel(){return `<section class="legal-prepare"><div><span class="eyebrow">BIBLIOTECA PREENCHÍVEL · ${LD.version}</span><h2>Os textos já estão escritos.</h2><p>${LD.docs.length} modelos e formulários para os 16 tipos da operação. Preencha a base da empresa e do carro, depois os dados do motorista ou do evento. Os modelos continuam sujeitos à revisão profissional.</p></div><div class="actions">${btn('Preparar um documento','legal-document-library','primary')}${btn('Pacote de entrada · '+LD.entryIds.length+' modelos','legal-document-entry')}${btn('Baixar biblioteca completa','legal-document-all')}</div><p class="caption">Seguro e financiamento incluem formulários de solicitação/conferência. A apólice e o contrato de crédito vêm dos fornecedores. Recibos, vistorias e acordos exigem os fatos reais do evento.</p></section>`;}
 function legalDocumentLibrary(guide=null){const list=guide?LD.docs.filter(d=>d.guide===Number(guide)):LD.docs;return `<div class="legal-library"><p>Escolha o documento. Você pode ler e baixar o modelo em branco ou preencher os campos antes de gerar.</p>${list.map(d=>`<article><span class="eyebrow">TIPO ${d.guide} · ${esc(d.kind)}</span><h3>${esc(d.title)}</h3>${d.notice?`<p>${esc(d.notice)}</p>`:''}<div class="actions">${btn('Preencher','legal-document-edit','primary',`data-id="${d.id}" aria-label="Preencher: ${esc(d.title)}"`)}${btn('Ler modelo','legal-document-read','',`data-id="${d.id}" aria-label="Ler modelo: ${esc(d.title)}"`)}</div></article>`).join('')}</div>`;}
 function legalDraftCapture(){const form=root.querySelector('#legal-document-form');if(form){const values=Object.fromEntries([...new FormData(form)].filter(([k])=>Object.hasOwn(LD.fields,k)));legalDraft.values={...legalDraft.values,...LD.clean(values)};}return legalDraft;}
 function legalField(f){const value=legalDraft.values[f.key]||'',attrs=`name="${f.key}" id="legal-field-${f.key}" autocomplete="off" maxlength="7000"`;const control=f.type==='textarea'?`<textarea ${attrs} rows="3">${esc(value)}</textarea>`:f.type==='select'?`<select ${attrs}><option value="">Escolha conscientemente</option>${f.options.map(o=>`<option ${value===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select>`:`<input ${attrs} type="${f.type==='date'?'date':'text'}" ${f.type==='money'?'inputmode="decimal" placeholder="1.000,00"':''} value="${esc(value)}">`;return `<label class="field ${f.type==='textarea'?'span2':''}" for="legal-field-${f.key}">${esc(f.label)}${control}${f.help?`<small>${esc(f.help)}</small>`:''}</label>`;}
 function legalDocumentEditor(input,capture=true){if(capture)legalDraftCapture();legalDraft.ids=LD.ids(input);const fs=LD.fieldsFor(legalDraft.ids);return `<div class="legal-editor"><p class="legal-draft-privacy"><strong>Preenchimento temporário.</strong> Estes campos ficam só na memória desta aba, fora do backup operacional e do armazenamento do navegador. Baixe o documento antes de atualizar ou fechar a página. A base exportada contém dados da empresa/carro: guarde-a em local privado.</p><div class="actions legal-editor-tools">${btn('Salvar base reutilizável','legal-document-base-export')}${btn('Carregar base','legal-document-base-import')}${btn('Trocar motorista / novo caso','legal-document-new-driver')}${btn('Limpar todos os campos','legal-document-clear')}</div><input id="legal-base-file" type="file" accept="application/json,.json" hidden><details><summary>Documentos selecionados (${legalDraft.ids.length})</summary><ul>${legalDraft.ids.map(id=>`<li>${esc(LD.get(id).title)}</li>`).join('')}</ul></details><form id="legal-document-form" autocomplete="off">${Object.entries(LD.groups).filter(([id])=>fs.some(f=>f.group===id)).map(([id,name],index)=>`<details class="legal-fields-group" ${index===0||id==='driver'?'open':''}><summary>${esc(name)} <small>· ${fs.filter(f=>f.group===id).length} campo(s)</small></summary><div class="fields gap">${fs.filter(f=>f.group===id).map(legalField).join('')}</div></details>`).join('')}<div class="legal-editor-submit"><p>Campo sem informação permanece marcado como pendente. Gerar uma minuta não assina nem libera o carro.</p><button type="submit" class="btn primary">Conferir e gerar prévia</button></div></form></div>`;}
 function legalDocumentsPreview(input,values,editable=true){const docs=LD.bundle(input,values),missing=[...new Set(docs.flatMap(d=>d.missing))];return `<div class="legal-prepared"><div class="notice ${missing.length?'amber':''}"><strong>${missing.length?'Faltam '+missing.length+' campos de preenchimento.':'Campos preenchidos · revisão profissional pendente.'}</strong><p>${missing.length?'O arquivo será identificado como rascunho incompleto.':'Conferir fatos, valores, cláusulas, anexos e assinaturas antes de usar.'}</p>${missing.length?`<details><summary>Ver campos em aberto</summary><ul>${missing.map(k=>`<li>${esc(LD.fields[k].label)}</li>`).join('')}</ul></details>`:''}</div><div class="actions gap">${editable?btn('Voltar ao preenchimento','legal-document-back','primary'):''}${editable&&!serverSession&&!missing.length&&LD.entryIds.every(id=>docs.some(d=>d.id===id))?btn('Vincular exemplo à operação','legal-document-link'):''}${btn('Baixar TXT'+(missing.length?' · rascunho':''),'legal-document-download','',`data-format="txt" data-blank="${!editable}" data-ids="${docs.map(d=>d.id).join(',')}"`)}${btn('Baixar para PDF'+(missing.length?' · rascunho':''),'legal-document-download','',`data-format="html" data-blank="${!editable}" data-ids="${docs.map(d=>d.id).join(',')}"`)}</div><p class="caption">O arquivo para PDF é HTML independente: abra e use Imprimir → Salvar como PDF. Nenhum arquivo é enviado para assinatura ou gravado no vínculo automaticamente. Os registros anteriores permanecem preservados.</p>${docs.map((d,index)=>`<details class="legal-prepared-document" ${index===0?'open':''}><summary>${esc(d.title)}</summary>${d.notice?`<p class="notice amber">${esc(d.notice)}</p>`:''}<pre class="co-document">${esc(d.body)}</pre></details>`).join('')}</div>`;}
 function legalDocumentAction(action,e){
  if(!action.startsWith('legal-document-'))return false;
  if(action==='legal-document-library'||action==='legal-document-guide'){open('Biblioteca de documentos',legalDocumentLibrary(e.dataset.guide));return true;}
  if(action==='legal-document-edit'||action==='legal-document-entry'){const list=action==='legal-document-entry'?LD.entryIds:[e.dataset.id];open('Preparar documentos',legalDocumentEditor(list));return true;}
  if(action==='legal-document-read'){open('Modelo para revisão',legalDocumentsPreview([e.dataset.id],{},false));return true;}
  if(action==='legal-document-all'){open('Biblioteca completa · modelos em branco',legalDocumentsPreview(LD.docs.map(d=>d.id),{},false));return true;}
  if(action==='legal-document-link'){if(serverSession)throw new RangeError('O vínculo deste ensaio é exclusivo da prévia fictícia.');const candidates=K.contracts(ops).filter(c=>c.modelId==='rental'&&c.status==='draft'&&/\bTESTE\b/i.test(c.driverName)&&/^TESTE-/i.test(c.vehiclePlate));open('Vincular pacote fictício',candidates.length?`<form id="legal-document-link-form"><p>Os oito textos serão guardados nesta versão da minuta e aparecerão juntos no app do motorista. Revisão, assinatura, caução e entrega continuam em etapas próprias.</p>${select('contractId','Minuta do ensaio',candidates[0].id,candidates.map(c=>[c.id,c.id+' · '+c.driverName+' · '+c.vehiclePlate]))}<label class="check gap"><input name="fictional" type="checkbox" required>Confirmo que todos os dados são fictícios, sem documentos pessoais reais. Este pacote será salvo no navegador e no backup do ensaio.</label><button class="btn primary gap" type="submit">Vincular os 8 documentos de teste</button></form>`:'<p>Cadastre um motorista com TESTE no nome, um carro com identificação TESTE- e crie uma minuta de locação para esse vínculo. Depois volte ao pacote preenchido.</p>'+btn('Voltar ao pacote','legal-document-show'));return true;}
  if(action==='legal-document-show'){open('Conferir documentos',legalDocumentsPreview(legalDraft.ids,legalDraft.values));return true;}
  if(action==='legal-document-back'){open('Preparar documentos',legalDocumentEditor(legalDraft.ids));return true;}
  if(action==='legal-document-new-driver'||action==='legal-document-clear'){legalDraftCapture();legalDraft.values=action==='legal-document-clear'?{}:LD.exportBase(legalDraft.values).values;open('Preparar documentos',legalDocumentEditor(legalDraft.ids,false));toast(action==='legal-document-clear'?'Preenchimento temporário limpo.':'Dados do motorista, evento e assinatura removidos. Base da empresa e carro preservada.');return true;}
  if(action==='legal-document-base-export'){legalDraftCapture();download('RODAVOLT-base-privada-de-preenchimento.json',JSON.stringify(LD.exportBase(legalDraft.values),null,2),'application/json');return true;}
  if(action==='legal-document-base-import'){root.querySelector('#legal-base-file').click();return true;}
  if(action==='legal-document-download'){const list=e.dataset.ids.split(','),v=e.dataset.blank==='true'?{}:legalDraft.values,html=e.dataset.format==='html';download('RODAVOLT-'+(list.length===1?list[0]:'pacote')+'-para-revisao.'+(html?'html':'txt'),html?LD.exportHtml(list,v):LD.exportText(list,v),html?'text/html;charset=utf-8':'text/plain;charset=utf-8');return true;}
  return false;
 }
 function legalDocumentSubmit(form){if(form.id==='legal-document-link-form'){if(serverSession)throw new RangeError('Este ensaio é exclusivo da prévia fictícia.');const f=new FormData(form),id=String(f.get('contractId')),candidate=structuredClone(ops);K.attachDemoPackage(candidate,id,{fictional:f.has('fictional'),values:legalDraft.values});ops=candidate;persist();render();open('Meu advogado · pacote vinculado',coContractBody(id));toast('Oito documentos vinculados. Revise e acompanhe as partes no próprio contrato.');return true;}if(form.id!=='legal-document-form')return false;legalDraftCapture();open('Conferir documentos',legalDocumentsPreview(legalDraft.ids,legalDraft.values));return true;}
 root.addEventListener('input',event=>{if(event.target.closest('#legal-document-form'))legalDraftCapture();});
 root.addEventListener('change',event=>{if(event.target.closest('#legal-document-form'))legalDraftCapture();if(event.target.id!=='legal-base-file')return;const file=event.target.files?.[0];if(!file)return;if(file.size>300000){reportError('Escolha uma base de até 300 KB.');return;}legalDraftCapture();file.text().then(raw=>{const base=LD.importBase(JSON.parse(raw));legalDraft.values={...Object.fromEntries(Object.entries(legalDraft.values).filter(([k])=>!LD.reusableGroups.includes(LD.fields[k].group))),...base};open('Preparar documentos',legalDocumentEditor(legalDraft.ids,false));toast('Base carregada nesta aba. Confira os dados antes de gerar.');}).catch(error=>reportError(error.message));});
